package com.worksphere.controller; import com.worksphere.dto.rating.*; import com.worksphere.service.RatingService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/ratings") public class RatingController {private final RatingService s;public RatingController(RatingService x){s=x;} @PostMapping public Object rate(Authentication a,@RequestBody RatingRequest r){return s.rate(a,r);} }
